<div class="editor-sections">
<section class="panel form-section"><div class="section-heading"><span>01</span><div><h2>Code</h2><p>What the customer types at checkout.</p></div></div><div class="form-grid compact-grid"><label class="full">Code<input name="code" value="<?= e($value('code')) ?>" maxlength="40" placeholder="SAVE10" style="text-transform:uppercase" required></label><label>Status<select name="status"><option value="ACTIVE" <?= $value('status','ACTIVE')==='ACTIVE'?'selected':'' ?>>Active</option><option value="INACTIVE" <?= $value('status')==='INACTIVE'?'selected':'' ?>>Inactive</option></select></label></div></section>

<section class="panel form-section"><div class="section-heading"><span>02</span><div><h2>Discount type</h2><p>Choose one mechanic per code.</p></div></div><div class="form-grid compact-grid"><label class="full">Type<select name="type" data-discount-type><option value="PERCENT_ORDER" <?= $value('type','PERCENT_ORDER')==='PERCENT_ORDER'?'selected':'' ?>>Percentage off entire order</option><option value="FIXED_ORDER" <?= $value('type')==='FIXED_ORDER'?'selected':'' ?>>Fixed amount off entire order</option><option value="PERCENT_PRODUCT" <?= $value('type')==='PERCENT_PRODUCT'?'selected':'' ?>>Percentage off a specific product</option><option value="PERCENT_CATEGORY" <?= $value('type')==='PERCENT_CATEGORY'?'selected':'' ?>>Percentage off a specific category</option><option value="FREE_DELIVERY" <?= $value('type')==='FREE_DELIVERY'?'selected':'' ?>>Free delivery (flag only — you honor it manually)</option></select></label>
<label class="full" data-discount-field="value">Value<input name="value" value="<?= e($value('value')) ?>" inputmode="decimal" placeholder="e.g. 10"><small data-discount-value-hint>Percentage (0–100) or a fixed amount in your store currency, depending on the type above.</small></label>
<label class="full" data-discount-field="scope_product_id"><?php $products=$products??[];?>Product<select name="scope_product_id"><option value="0">Choose a product…</option><?php foreach($products as$p):?><option value="<?= e($p['id']) ?>" <?= (int)$value('scope_product_id')===(int)$p['id']?'selected':'' ?>><?= e($p['name']) ?></option><?php endforeach ?></select></label>
<label class="full" data-discount-field="scope_category_id"><?php $categories=$categories??[];?>Category<select name="scope_category_id"><option value="0">Choose a category…</option><?php foreach($categories as$c):?><option value="<?= e($c['id']) ?>" <?= (int)$value('scope_category_id')===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></label>
