<section class="panel form-section"><div class="section-heading"><span>03</span><div><h2>Limits</h2><p>All optional — leave blank for no limit.</p></div></div><div class="form-grid compact-grid"><label>Minimum order amount <span class="optional">Optional</span><input name="min_order_amount" value="<?= e($value('min_order_amount')) ?>" inputmode="decimal" placeholder="e.g. 25.00"></label><label>Total use limit <span class="optional">Optional</span><input name="usage_limit" value="<?= e($value('usage_limit')) ?>" inputmode="numeric" placeholder="e.g. 100"></label><label>Uses per customer <span class="optional">Optional</span><input name="usage_limit_per_customer" value="<?= e($value('usage_limit_per_customer')) ?>" inputmode="numeric" placeholder="e.g. 1"></label></div></section>

